+	byte_stream_copy_to_uint32_little_endian(
+	 &( data[ 48 ] ),
+	 internal_usn_record->security_descriptor_identifier );
+
+	byte_stream_copy_to_uint32_little_endian(
+	 &( data[ 52 ] ),
+	 internal_usn_record->file_attribute_flags );
