+	{
+		return( 1 );
+	}
+	for( string_index = 0;
+	     string_index < string_size;
+	     string_index++ )
+	{
+		switch( string[ string_index ] )
+		{
+			case '\\':
+				if( fprintf(
+				     stream,
+				     "\\\\" ) < 0 )
+				{
+					goto on_error;
+				}
+				break;
+
+			case '|':
+				if( fprintf(
+				     stream,
+				     "\\|" ) < 0 )
+				{
+					goto on_error;
+				}
