+/* Prints an escaped USN timeline string value
+ * Returns 1 if successful or -1 on error
+ */
+static int info_handle_usn_timeline_string_fprint(
+            FILE *stream,
+            const uint8_t *string,
+            size_t string_size,
+            libcerror_error_t **error )
+{
+	static char *function = "info_handle_usn_timeline_string_fprint";
+	size_t string_index   = 0;
+
+	if( string == NULL )
+	{
+		return( 1 );
+	}
+	for( string_index = 0;
+	     string_index < string_size;
+	     string_index++ )
+	{
+		switch( string[ string_index ] )
+		{
+			case '\\':
+				if( fprintf(
+				     stream,
+				     "\\\\" ) < 0 )
+				{
+					goto on_error;
+				}
+				break;
+
+			case '|':
+				if( fprintf(
+				     stream,
+				     "\\|" ) < 0 )
+				{
+					goto on_error;
+				}
+				break;
+
+			case '\n':
+				if( fprintf(
+				     stream,
+				     "\\n" ) < 0 )
+				{
+					goto on_error;
+				}
+				break;
+
+			case '\r':
+				if( fprintf(
+				     stream,
+				     "\\r" ) < 0 )
+				{
+					goto on_error;
+				}
+				break;
+
+			default:
+				if( fputc(
+				     (int) string[ string_index ],
+				     stream ) == EOF )
+				{
+					goto on_error;
+				}
+				break;
+		}
+	}
+	return( 1 );
+
+on_error:
+	libcerror_error_set(
+	 error,
+	 LIBCERROR_ERROR_DOMAIN_IO,
+	 LIBCERROR_IO_ERROR_WRITE_FAILED,
+	 "%s: unable to write string value.",
+	 function );
+
+	return( -1 );
+}
