/* Prints a FILETIME as an USN timeline value
 * Returns 1 if successful or -1 on error
 */
static int info_handle_usn_timeline_filetime_fprint(
            FILE *stream,
            uint64_t filetime_value,
            libcerror_error_t **error )
{
	char date_time_string[ 48 ];
	libfdatetime_filetime_t *filetime = NULL;
	static char *function             = "info_handle_usn_timeline_filetime_fprint";
	int result                        = 0;

	if( filetime_value == 0 )
	{
		return( fprintf(
		         stream,
		         "Not set" ) >= 0 ? 1 : -1 );
	}
	if( libfdatetime_filetime_initialize(
	     &filetime,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_INITIALIZE_FAILED,
		 "%s: unable to create FILETIME.",
		 function );

		goto on_error;
	}
	if( libfdatetime_filetime_copy_from_64bit(
	     filetime,
	     filetime_value,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_COPY_FAILED,
		 "%s: unable to copy 64-bit value to FILETIME.",
		 function );

		goto on_error;
	}
	result = libfdatetime_filetime_copy_to_utf8_string(
	          filetime,
	          (uint8_t *) date_time_string,
	          48,
	          LIBFDATETIME_STRING_FORMAT_TYPE_CTIME | LIBFDATETIME_STRING_FORMAT_FLAG_DATE_TIME_NANO_SECONDS,
	          error );

	if( result != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_COPY_FAILED,
		 "%s: unable to copy FILETIME to string.",
		 function );

		goto on_error;
	}
	if( fprintf(
	     stream,
	     "%s UTC",
	     date_time_string ) < 0 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_IO,
		 LIBCERROR_IO_ERROR_WRITE_FAILED,
		 "%s: unable to write date time string.",
		 function );

		goto on_error;
	}
	if( libfdatetime_filetime_free(
	     &filetime,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_FINALIZE_FAILED,
		 "%s: unable to free FILETIME.",
		 function );

		return( -1 );
	}
	return( 1 );

on_error:
	if( filetime != NULL )
	{
		libfdatetime_filetime_free(
		 &filetime,
		 NULL );
	}
	return( -1 );
}

/* Prints an escaped USN timeline string value
 * Returns 1 if successful or -1 on error
 */
static int info_handle_usn_timeline_string_fprint(
            FILE *stream,
            const uint8_t *string,
            size_t string_size,
            libcerror_error_t **error )
{
	static char *function = "info_handle_usn_timeline_string_fprint";
	size_t string_index   = 0;

	if( string == NULL )
	{
		return( 1 );
	}
	for( string_index = 0;
	     string_index < string_size;
	     string_index++ )
	{
		switch( string[ string_index ] )
		{
			case '\\':
				if( fprintf(
				     stream,
				     "\\\\" ) < 0 )
				{
					goto on_error;
				}
				break;

			case '|':
				if( fprintf(
				     stream,
				     "\\|" ) < 0 )
				{
					goto on_error;
				}
				break;

			case '\n':
				if( fprintf(
				     stream,
				     "\\n" ) < 0 )
				{
					goto on_error;
				}
				break;

			case '\r':
				if( fprintf(
				     stream,
				     "\\r" ) < 0 )
				{
					goto on_error;
				}
				break;

			default:
				if( fputc(
				     (int) string[ string_index ],
				     stream ) == EOF )
				{
					goto on_error;
				}
				break;
		}
	}
	return( 1 );

on_error:
	libcerror_error_set(
	 error,
	 LIBCERROR_ERROR_DOMAIN_IO,
	 LIBCERROR_IO_ERROR_WRITE_FAILED,
	 "%s: unable to write string value.",
	 function );

	return( -1 );
}

